   "issues": [
     {"issue": null, "type": 1, "prob": 0.05},
     {"issue": null, "type": 2, "prob": 0.05}
   ]},
  {"clause_id": "c008",
   "issues": [
     {"issue": "\"Shall comply with the Servicing Standards ... in accordance with their terms and Section A of Exhibit E\" leaves open whether compliance is an absolute per-loan duty or is measured only by the aggregate metrics and error-rate thresholds of Exhibit E. That is the classic fight between a servicer and an enforcing party over what counts as a violation.", "type": 1, "prob": 0.55},
